from pathlib import Path

scenario = Path("scenarios/missions/d66_lvl10-16_mission_01_blacksun.md")
s = scenario.read_text(encoding="utf-8")

old62 = """  - 【1】中立  \n    屋上の影がこちらを観察している。素通りする場合、戦闘を回避できる。その場合、戦利品は入手できない。次に発生する戦闘において、最初の防御ロールに -1 の修正を受ける。\n"""
new62 = """  - 【1】中立  \n    屋上の影がこちらを観察している。素通りする場合、戦闘を回避できる。その場合、戦利品は入手できない。次に発生する戦闘において、最初の防御ロールに -1 の修正を受ける。中立を確認した後で戦闘を開始する場合、敵の反応を【敵対的】として扱い、分隊側が先攻となる。この先攻は行動順だけを変更し、Core v1.01の遭遇時選択【先制攻撃】を行ったものとしては扱わないため、敵の反応は【死ぬまで戦う】へ変更しない。\n"""
if s.count(old62) != 1:
    raise SystemExit(f"Event62 neutral anchor count must be 1, got {s.count(old62)}")
s = s.replace(old62, new62, 1)

old65 = """  - 【1-2】中立  \n    車両は通過中。戦闘を選ばない限り素通りできる。\n"""
new65 = """  - 【1-2】中立  \n    車両は通過中。戦闘を選ばない限り素通りできる。中立を確認した後で戦闘を開始する場合、敵の反応を【敵対的】として扱い、分隊側が先攻となる。この先攻は行動順だけを変更し、Core v1.01の遭遇時選択【先制攻撃】を行ったものとしては扱わないため、敵の反応は【死ぬまで戦う】へ変更しない。\n"""
if s.count(old65) != 1:
    raise SystemExit(f"Event65 neutral anchor count must be 1, got {s.count(old65)}")
s = s.replace(old65, new65, 1)
scenario.write_text(s, encoding="utf-8")

audit = Path("docs/SCENARIO_V1_01_RESOURCE_BALANCE_AUDIT.md")
a = audit.read_text(encoding="utf-8")
heading = "## 50. Black Sun 出目62・65【中立】後の任意交戦 — 採用済み"
section = """

## 50. Black Sun 出目62・65【中立】後の任意交戦 — 採用済み

ユーザー承認により、出目62【屋上の影】および出目65【つぎはぎだらけの武装トラック】で【中立】を確認した後、プレイヤー側から戦闘を開始する場合の処理を出目61と統一する。

- 【中立】確認後に戦闘を開始する場合、敵の反応を【敵対的】として扱う。
- 戦闘開始時の行動順は分隊側を先攻とする。
- この先攻は行動順だけを変更するシナリオ固有指定であり、Core v1.01の遭遇時選択【先制攻撃】としては扱わない。
- したがって、この任意交戦だけを理由として敵の反応を【死ぬまで戦う】へ変更しない。
- 出目62の【高所からの狙撃】にある「反応を見ずに戦闘を開始した場合は敵が必ず先攻」は、反応【中立】を確認した後の任意交戦には適用しない。
- 出目62・65はいずれも高脅威目標であるため、【敵対的】になってもCore v1.01の敵戦闘集団用の自動撤退条件は適用しない。ただし出目62にはシナリオ固有の撤退条件があるため、その条件は通常どおり適用する。

これにより、出目61・62・65の【中立】後の任意交戦を共通処理としつつ、出目62の「反応を見ずに攻撃した場合」の固有先攻ルールと明確に区別する。
"""
if heading not in a:
    a = a.rstrip() + section + "\n"
audit.write_text(a, encoding="utf-8")
